use peersus_core::config::Language;

// Each row follows Language::ALL without English, whose source text is the message id.
macro_rules! messages {
    ($($english:literal => [$($translated:literal),+ $(,)?]),* $(,)?) => {
        pub fn translate(language: Language, english: &str) -> &str {
            let index = match language {
                Language::English => return english,
                Language::Romanian => 0, Language::German => 1, Language::French => 2,
                Language::Spanish => 3, Language::Italian => 4, Language::Portuguese => 5,
                Language::Polish => 6, Language::Dutch => 7, Language::Turkish => 8,
                Language::Czech => 9, Language::Swedish => 10,
            };
            match english {
                $($english => { const ROW: [&str; 11] = [$($translated),+]; ROW[index] },)*
                _ => english,
            }
        }

        /// Whether `english` is a message of the catalog. Made from the same rows as `translate`, so that the two cannot disagree:
        /// `translate` gives a text back unchanged when it is not there, which is no way to tell a missing text from one that is the same
        /// in every language.
        pub fn has(english: &str) -> bool {
            matches!(english, $($english)|*)
        }
    };
}

